INSERT INTO public.dueno_accesos_v53(correo,negocio,activo)
SELECT lower(u.email),'medussa-tatto-studio',true FROM public.piloto_administradores a JOIN auth.users u ON u.id=a.usuario_id
WHERE u.email IS NOT NULL AND u.email_confirmed_at IS NOT NULL AND (u.banned_until IS NULL OR u.banned_until<now())
ON CONFLICT (correo,negocio) DO UPDATE SET activo=true;
COMMIT;
